 1→import { defineConfig, devices } from '@playwright/test';
 2→import { existsSync } from 'fs';
 3→import { resolve } from 'path';
 4→
 5→// Extra LD_LIBRARY_PATH for VPS environments with ~/playwright-libs/lib/
 6→function buildLaunchEnv(): Record<string, string> | undefined {
 7→  const home = process.env['HOME'];
 8→  if (!home) return undefined;
 9→  const playwrightLibs = resolve(home, 'playwright-libs', 'lib');
10→  if (!existsSync(playwrightLibs)) return undefined;
11→  return {
12→    LD_LIBRARY_PATH: [playwrightLibs, process.env['LD_LIBRARY_PATH']].filter(Boolean).join(':'),
13→  };
14→}
15→
16→export default defineConfig({
17→  testDir: './e2e',
18→  outputDir: './e2e/test-results',
19→  fullyParallel: true,
20→  forbidOnly: !!process.env['CI'],
21→  retries: process.env['CI'] ? 2 : 0,
22→  workers: process.env['CI'] ? 1 : undefined,
23→  reporter: 'html',
24→  use: {
25→    baseURL: 'http://localhost:4200',
26→    trace: 'on-first-retry',
27→    screenshot: 'only-on-failure',
28→    launchOptions: {
29→      env: buildLaunchEnv(),
30→    },
31→  },
32→  projects: [
33→    {
34→      name: 'chromium',
35→      use: { ...devices['Desktop Chrome'] },
36→    },
37→  ],
38→  webServer: {
39→    command: 'npm run start',
40→    url: 'http://localhost:4200',
41→    reuseExistingServer: !process.env['CI'],
42→    timeout: 120_000,
43→  },
44→});
